input.content:
// Byte-exact differential harness: runs the Python executable and the Node port with an
// IDENTICAL argv array, compares stdout / stderr / exit code byte for byte.
//
//   node /workspace/verify/cmp.mjs --a hello --b 5
//     -> compares one case, prints PASS/FAIL + diff detail
//
//   node /workspace/verify/cmp.mjs --cases <file.json>
//     -> file.json is a JSON array of argv arrays, e.g. [["--a","x","--b","1"], ["--b","2"]]
//        prints one line per case and a summary; exits 1 if any case fails.
//
// Nothing here ships to /output; this is test scaffolding only.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test11_executable';
const JS = '/output/test11.mjs';

function run(cmd, argv) {
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], {
    encoding: 'buffer',
    maxBuffer: 1 << 28,
  });
  return {
    out: r.stdout ?? Buffer.alloc(0),
    err: r.stderr ?? Buffer.alloc(0),
    code: r.status,
  };
}

// argparse's prog name differs by design (test11_executable vs test11.mjs). Normalise it
// so stderr/usage text can still be compared structurally.
function normProg(buf) {
  return buf.toString('utf8')
    .replaceAll('test11_executable', '{PROG}')
    .replaceAll('test11.mjs', '{PROG}');
}

export function compare(argv) {
  const py = run([EXE], argv);
  const js = run(['node', JS], argv);
  const problems = [];
  if (!py.out.equals(js.out)) problems.push('stdout');
  if (normProg(py.err) !== normProg(js.err)) problems.push('stderr');
  if (py.code !== js.code) problems.push(`exit(py=${py.code} js=${js.code})`);
  return { argv, py, js, problems, ok: problems.length === 0 };
}

function show(label, buf) {
  const s = typeof buf === 'string' ? buf : buf.toString('utf8');
  return `${label} (${s.length} chars):\n${JSON.stringify(s)}`;
}

function report(res) {
  if (res.ok) {
    console.log(`PASS ${JSON.stringify(res.argv)}`);
    return;
  }
  console.log(`FAIL ${JSON.stringify(res.argv)}  [${res.problems.join(', ')}]`);
  if (res.problems.includes('stdout')) {
    const a = res.py.out.toString('utf8').split('\n');
    const b = res.js.out.toString('utf8').split('\n');
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
      if (a[i] !== b[i]) {
        console.log(`  stdout line ${i + 1} differs`);
        console.log(`    py: ${JSON.stringify(a[i])}`);
        console.log(`    js: ${JSON.stringify(b[i])}`);
      }
    }
  }
  if (res.problems.includes('stderr')) {
    console.log(`  ${show('py stderr', normProg(res.py.err))}`);
    console.log(`  ${show('js stderr', normProg(res.js.err))}`);
  }
}

const argv = process.argv.slice(2);
if (argv[0] === '--cases') {
  const cases = JSON.parse(readFileSync(argv[1], 'utf8'));
  let fails = 0;
  for (const c of cases) {
    const res = compare(c);
    if (!res.ok) fails++;
    report(res);
  }
  console.log(`\n${cases.length - fails}/${cases.length} passed`);
  process.exitCode = fails ? 1 : 0;
} else if (argv.length) {
  const res = compare(argv);
  report(res);
  process.exitCode = res.ok ? 0 : 1;
}

