// Independent cross-check probe (main-agent only; not part of /output).
// Feeds batches of code points to the reference executable and records, per code point,
// whether Python's repr() escaped it and how. Batches many code points per process run:
// each candidate is wrapped as  |<hex>=<char>|  so the repr can be parsed back.
import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test11_executable';

function reprOfName(str) {
  const r = spawnSync(EXE, ['--a', str, '--b', '1'], { encoding: 'utf8', maxBuffer: 1 << 26 });
  // 5th stdout line is repr({'name': <a>, 'age': <b>})
  const lines = r.stdout.split('\n');
  const i = lines.findIndex(l => l.startsWith("{'name': ") || l.startsWith('{"name": '));
  return { line: lines[i], all: r.stdout, err: r.stderr };
}

const cps = [];
// dense low ranges
for (let c = 0x00; c <= 0xff; c++) cps.push(c);
// interesting singletons / ranges
const extra = [
  0x100, 0x2d0, 0x34f, 0x378, 0x380, 0x483, 0x591, 0x600, 0x605, 0x61c, 0x6dd, 0x70f,
  0x8e2, 0x1680, 0x180e, 0x1c80, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006,
  0x2007, 0x2008, 0x2009, 0x200a, 0x200b, 0x200c, 0x200d, 0x200e, 0x200f, 0x2028, 0x2029,
  0x202a, 0x202b, 0x202c, 0x202d, 0x202e, 0x202f, 0x205f, 0x2060, 0x2061, 0x2064, 0x2065,
  0x2066, 0x206f, 0x2070, 0x3000, 0x303f, 0xd7fb, 0xe000, 0xf8ff, 0xfdd0, 0xfeff, 0xfff0,
  0xfff9, 0xfffb, 0xfffe, 0xffff,
  0x10000, 0x1000c, 0x101fd, 0x1039f, 0x110bd, 0x13430, 0x1d173, 0x1d7ce, 0x1f600,
  0xe0001, 0xe0020, 0xe007f, 0xf0000, 0xffffd, 0x10fffd,
];
cps.push(...extra);

const results = {};
const BATCH = 40;
for (let i = 0; i < cps.length; i += BATCH) {
  const chunk = cps.slice(i, i + BATCH);
  const parts = chunk.map(c => `|${c.toString(16)}=${String.fromCodePoint(c)}|`);
  const { line, err } = reprOfName(parts.join(''));
  if (!line) { console.log('NO LINE for batch', i, err.slice(0, 200)); continue; }
  // strip the wrapper: {'name': <repr>, 'age': 1}
  const m = line.match(/^\{'name': (.*), 'age': 1\}$/);
  if (!m) { console.log('UNPARSED', JSON.stringify(line.slice(0, 200))); continue; }
  const body = m[1];
  // body is a quoted python string; split on the |hex=  markers
  const segs = body.slice(1, -1).split('|').filter(s => s.length);
  for (const seg of segs) {
    const mm = seg.match(/^([0-9a-f]+)=(.*)$/);
    if (mm) results[parseInt(mm[1], 16)] = mm[2];
  }
}

const rows = [];
for (const c of cps) {
  const got = results[c];
  if (got === undefined) { rows.push([c, 'MISSING']); continue; }
  const literal = String.fromCodePoint(c);
  const escaped = got !== literal;
  rows.push([c, escaped ? 'ESC' : 'raw', got]);
}
writeFileSync('/workspace/probe_printable.json', JSON.stringify(rows, null, 0));
console.log('escaped code points:');
console.log(rows.filter(r => r[1] === 'ESC').map(r => `U+${r[0].toString(16).toUpperCase().padStart(4, '0')} -> ${r[2]}`).join('\n'));
console.log('\nMISSING:', rows.filter(r => r[1] === 'MISSING').map(r => r[0].toString(16)).join(' '));
console.log('\nraw (printable) count:', rows.filter(r => r[1] === 'raw').length);

