// Does Node 18's \p{...} agree with the executable's Python unicodedata?
// Probes code points assigned in successive Unicode versions. A disagreement means a
// \p{Cn}-based implementation is unsafe and needs a pinned table.
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

const CANDIDATES = [
  // [codepoint, unicode version that assigned it, note]
  [0x0870, '14.0', 'Arabic Ext-B'],
  [0x1E7E0, '14.0', 'Ethiopic Ext-B'],
  [0x1E030, '15.0', 'Cyrillic Ext-D'],
  [0x11F00, '15.0', 'Kawi'],
  [0x1E4D0, '15.0', 'Nag Mundari'],
  [0x1DFA, '15.0', 'combining'],
  [0x31EF, '15.1', 'CJK ideographic description'],
  [0x2EBF0, '15.1', 'CJK Ext I'],
  [0x10D40, '16.0', 'Garay digits'],
  [0x11380, '16.0', 'Tulu-Tigalari'],
  [0x16D40, '16.0', 'Kirat Rai'],
  [0x1E5D0, '16.0', 'Ol Onal'],
  [0x105C0, '16.0', 'Todhri'],
  [0x11BC0, '16.0', 'Sunuwar'],
  [0x16100, '16.0', 'Gurung Khema'],
  [0x1CC00, '16.0', 'misc symbols'],
  [0x0897, '16.0', 'Arabic mark'],
  [0x10D8E, '17.0', 'Garay (late)'],
  [0x1E6C0, '17.0', 'Tolong Siki'],
  [0x11B60, '17.0', 'Beria Erfe'],
  [0xFB18, 'ancient', 'assigned long ago (control group)'],
];

function pyEscapes(cp) {
  const s = `|${cp.toString(16)}=${String.fromCodePoint(cp)}|`;
  const r = spawnSync(EXE, ['--a', s, '--b', '1'], { encoding: 'utf8' });
  const line = r.stdout.split('\n').find(l => l.startsWith("{'name': "));
  if (!line) return { err: r.stderr.trim() };
  const body = line.slice("{'name': ".length).replace(/, 'age': 1\}$/, '');
  const inner = body.slice(1, -1);
  const seg = inner.split('|').filter(Boolean)[0] || '';
  const got = seg.split('=')[1] ?? '';
  return { escaped: got !== String.fromCodePoint(cp), repr: got };
}

// Node's own view, via Unicode property escapes
const NONPRINT = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
function nodeEscapes(cp) {
  const ch = String.fromCodePoint(cp);
  if (cp === 0x20) return false;
  return NONPRINT.test(ch);
}

console.log('cp        ver     python  node    agree  note');
let disagree = 0;
for (const [cp, ver, note] of CANDIDATES) {
  const py = pyEscapes(cp);
  const nd = nodeEscapes(cp);
  const ok = py.escaped === nd;
  if (!ok) disagree++;
  console.log(
    `U+${cp.toString(16).toUpperCase().padStart(5, '0')}  ${ver.padEnd(7)} ` +
    `${String(py.escaped).padEnd(7)} ${String(nd).padEnd(7)} ${ok ? 'yes' : 'NO '}    ${note}`
  );
}
console.log(`\ndisagreements: ${disagree}/${CANDIDATES.length}`);
console.log('node process.versions.unicode =', process.versions.unicode, ' icu =', process.versions.icu);

