// Lead-agent oracle check: replays /workspace/golden/corpus.json against /output/test11.mjs
// and reports byte-level differences. Independent of any subagent's self-report.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const corpus = JSON.parse(readFileSync('/workspace/golden/corpus.json', 'utf8'));
const JS = '/output/test11.mjs';

// The program name in argparse messages legitimately differs (test11_executable vs test11.mjs).
const normProg = s => s.replaceAll('test11_executable', '{PROG}').replaceAll('test11.mjs', '{PROG}');

let pass = 0;
const fails = [];
for (const c of corpus) {
  const r = spawnSync('node', [JS, ...c.argv], { encoding: 'buffer', maxBuffer: 1 << 28 });
  const gotOut = r.stdout ?? Buffer.alloc(0);
  const gotErr = r.stderr ?? Buffer.alloc(0);
  const wantOut = Buffer.from(c.stdout, 'base64');
  const wantErr = Buffer.from(c.stderr, 'base64');

  const bad = [];
  if (!gotOut.equals(wantOut)) bad.push('stdout');
  if (normProg(gotErr.toString('utf8')) !== normProg(wantErr.toString('utf8'))) bad.push('stderr');
  if (r.status !== c.code) bad.push(`exit(want=${c.code} got=${r.status})`);

  if (bad.length === 0) { pass++; continue; }
  fails.push({ argv: c.argv, bad, wantOut: wantOut.toString('utf8'), gotOut: gotOut.toString('utf8'),
    wantErr: wantErr.toString('utf8'), gotErr: gotErr.toString('utf8') });
}

console.log(`GOLDEN: ${pass}/${corpus.length} passed, ${fails.length} failed`);
for (const f of fails.slice(0, 25)) {
  console.log(`\nFAIL ${JSON.stringify(f.argv)}  [${f.bad.join(', ')}]`);
  if (f.bad.includes('stdout')) {
    const a = f.wantOut.split('\n'), b = f.gotOut.split('\n');
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
      if (a[i] !== b[i]) {
        console.log(`  line ${i + 1}:`);
        console.log(`    want: ${JSON.stringify(a[i])}`);
        console.log(`    got : ${JSON.stringify(b[i])}`);
      }
    }
  }
  if (f.bad.includes('stderr')) {
    console.log(`  want stderr: ${JSON.stringify(f.wantErr)}`);
    console.log(`  got  stderr: ${JSON.stringify(f.gotErr)}`);
  }
}
if (fails.length > 25) console.log(`\n... and ${fails.length - 25} more failures`);
process.exitCode = fails.length ? 1 : 0;

